/* Interactive prototype workflows. Official records remain untouched. */
const legacyAdminEconomy=adminEconomy,legacyTelemetry=telemetry,legacyUpdateNav=updateNav;
let adminCircuit='monza',adminSplit='1',economySplit='1',economyMode='precios',economySearch='',activeEconomyTeam=0,activeEconomyPilot=null;
const raceDrafts={};let savedSchedules={};try{savedSchedules=JSON.parse(localStorage.getItem('bugambra-schedules-v1')||'{}')}catch{}
const demoTeams=[{name:'Aurora Racing',balance:42.5,points:148,initial:100,market:-62,clauses:-14,pointsIncome:8,pole:2,fast:1,participation:4,clean:2,rivalry:0,season:0,adjustment:1.5},{name:'Vértice GP',balance:51,points:184,initial:100,market:-70,clauses:-3,pointsIncome:12,pole:3,fast:1,participation:4,clean:2,rivalry:2,season:0,adjustment:0},{name:'Nébula Motorsport',balance:38,points:121,initial:100,market:-75,clauses:-4,pointsIncome:8,pole:1,fast:0,participation:4,clean:2,rivalry:2,season:0,adjustment:0}];
const demoContracts=pilots.map((p,i)=>({pilot:i,price:[44,18,48,37,22,38][i],retention:[39,17,42,33,20,34][i],clause:[56,25,60,45,28,46][i]}));
function draftKey(){return adminSplit+':'+adminCircuit}
function raceDraft(){return raceDrafts[draftKey()]??=( {rows:pilots.map(p=>({q:circuits[adminCircuit].status==='cerrada'?String(p.q??''):'',pos:circuits[adminCircuit].status==='cerrada'?String(p.pos??''):'',status:circuits[adminCircuit].status==='cerrada'?(p.status||'Clasificado'):'Posición desconocida',fast:false})),sanctions:[],reason:''})}
function scheduleData(key=adminCircuit){return savedSchedules[key]||{round:key==='silverstone'?'9':key==='monza'?'8':key==='spa'?'7':'10',date:key==='silverstone'?'2026-10-18':key==='monza'?'2026-10-04':key==='spa'?'2026-09-27':'2026-10-25',time:'21:00',url:'',lap:''}}
function splitSelect(id,value,handler){return `<label class="field">Split<select id="${id}" onchange="${handler}">${['1','2','3'].map(n=>`<option value="${n}" ${value===n?'selected':''}>Split ${n}${n==='1'?' · demo':''}</option>`).join('')}</select></label>`}
function switchAdminRace(){captureRace();adminCircuit=$('#admin-circuit').value;adminSplit=$('#admin-split').value;render()}
function captureRace(){const d=raceDraft();if(!document.querySelector('#reason'))return;d.reason=$('#reason').value;d.rows.forEach((r,i)=>{if(!document.querySelector('#qualy-'+i))return;r.q=$('#qualy-'+i).value;r.pos=$('#pos-'+i).value;r.status=$('#status-'+i).value;r.fast=$('#lap-'+i).checked})}
adminRace=function(){const c=circuits[adminCircuit],d=raceDraft(),s=scheduleData();return `<div class="admin-toolbar">${splitSelect('admin-split',adminSplit,'switchAdminRace()')}<label class="field" style="flex:1">Circuito<select id="admin-circuit" onchange="switchAdminRace()">${Object.entries(circuits).map(([k,v])=>`<option value="${k}" ${k===adminCircuit?'selected':''}>${v.name} · ${v.status==='cerrada'?'Acta cerrada':'Próxima carrera'}</option>`).join('')}</select></label>${tag(c.status==='cerrada'?'ACTA CERRADA':'ANTES DE LA CARRERA',c.status==='cerrada'?'amber':'green')}</div>${adminSplit!=='1'?'<div class="card empty">No hay carreras de ejemplo en este split. Selecciona Split 1 para probar los formularios.</div>':`<section class="card pad schedule-card"><div class="card-top"><div><div class="eyebrow">01 · PREPARAR LA CARRERA</div><h2 style="margin-top:8px">Programación y vídeo · ${c.track}</h2></div>${tag(savedSchedules[adminCircuit]?'GUARDADO LOCAL':'DEMO',savedSchedules[adminCircuit]?'green':'')}</div><p class="small">Guarda el horario y la vuelta de referencia antes de la carrera. Horario de Madrid.</p><div class="schedule-layout"><form id="schedule-form" onsubmit="event.preventDefault();reviewSchedule()"><div class="schedule-fields"><label class="field">N.º de carrera<input id="schedule-round" type="number" min="1" step="1" required value="${esc(s.round)}"></label><label class="field">Fecha<input id="schedule-date" type="date" required value="${esc(s.date)}"></label><label class="field">Hora · Madrid<input id="schedule-time" type="time" required value="${esc(s.time)}"></label><label class="field full">URL de la vuelta rápida · YouTube<input id="schedule-url" type="url" placeholder="https://www.youtube.com/watch?v=…" value="${esc(s.url)}"></label><label class="field full">Tiempo de referencia (opcional)<input id="schedule-lap" placeholder="1:23.456" pattern="[0-9]+:[0-5][0-9]\\.[0-9]{3}" value="${esc(s.lap)}"></label></div><div class="actions"><button class="btn primary" type="submit">Revisar y guardar horario</button><button class="btn" type="button" onclick="previewScheduleVideo()">Previsualizar vídeo</button></div><p class="status-local">Prueba local: se conserva en este navegador, sin publicar en la liga.</p></form><div><div class="hotlap-preview" id="schedule-preview"><div><span class="play-round">▶</span><h3>${c.track}</h3><p>${s.url?'Vídeo preparado · pulsa Previsualizar':'Vídeo pendiente de publicación'}</p></div></div><p class="small">El reproductor se carga solo al pulsar. La programación es independiente del acta.</p></div></div></section><section class="card pad"><div class="card-top"><div><div class="eyebrow">02 · RESULTADOS Y DECISIONES</div><h2 style="margin-top:8px">Acta · ${c.track}</h2></div>${tag('BORRADOR')}</div><p class="small">Marca la vuelta rápida en la fila del piloto. Abre «Sanción» para registrar una decisión FIA o reglamentaria.</p>${pilots.map((p,i)=>{let r=d.rows[i];return `<div class="race-entry"><div class="identity" style="--team-color:${teamColor(p.team)}"><span class="driver-number">${p.n}</span><div><h3>${p.name}</h3><span class="small">${p.team}</span></div></div><label class="field">Qualy<input id="qualy-${i}" type="number" min="1" max="${pilots.length}" step="1" value="${esc(r.q)}" onchange="captureRace()"></label><label class="field">Carrera<input id="pos-${i}" type="number" min="1" max="${pilots.length}" step="1" value="${esc(r.pos)}" ${r.status!=='Clasificado'?'disabled':''} onchange="captureRace()"></label><label class="field">Estado<select id="status-${i}" onchange="syncPosition(${i});captureRace()">${['Clasificado','DNF','No corrió','Posición desconocida'].map(st=>`<option ${r.status===st?'selected':''}>${st}</option>`).join('')}</select></label><label class="lap-check"><input type="checkbox" id="lap-${i}" ${r.fast?'checked':''} ${r.status==='No corrió'?'disabled':''} onchange="selectFastest(${i})">V. rápida</label><div><button class="btn sanction-btn" onclick="sanctionForm(${i})">＋ Sanción</button><span class="sanction-count">${d.sanctions.filter(x=>x.pilot===i).length?d.sanctions.filter(x=>x.pilot===i).length+' decisión(es) en borrador':'Sin decisión en borrador'}</span></div></div>`}).join('')}<div class="review-box"><h2>Decisiones FIA y sanciones reglamentarias</h2><div class="race-fia-list">${d.sanctions.length?d.sanctions.map((x,i)=>`<div class="fia-draft"><div><strong>${pilots[x.pilot].name} · ${esc(x.kind)}</strong><p>${esc(x.seconds)} segundos · ${esc(x.rule)}</p><p>${esc(x.reason)}</p><span class="small">${esc(x.ref)} · Borrador, sin aplicar</span></div><div class="compact-actions">${btn('Editar',`sanctionForm(${x.pilot},${i})`)}${btn('Quitar',`removeSanction(${i})`)}</div></div>`).join(''):'<div class="info">No hay sanciones en el borrador. Cero puntos, DNF y no corrió son estados independientes.</div>'}</div><label class="field" style="margin-top:22px">Motivo y referencia oficial del acta<textarea id="reason" onchange="captureRace()" placeholder="Obligatorio para revisar la carrera">${esc(d.reason)}</textarea></label><div class="actions">${btn('Revisar impacto del acta','reviewRace()',true)}</div></div></section>`}`};
syncPosition=function(i){let st=$('#status-'+i).value;$('#pos-'+i).disabled=st!=='Clasificado';if(st!=='Clasificado')$('#pos-'+i).value='';$('#lap-'+i).disabled=st==='No corrió';if(st==='No corrió')$('#lap-'+i).checked=false};
function selectFastest(i){if($('#lap-'+i).checked)pilots.forEach((_,j)=>{if(i!==j)$('#lap-'+j).checked=false});captureRace()}
function sanctionForm(pilot,index=null){captureRace();const x=index===null?{kind:'Decisión FIA',seconds:'',reason:'',rule:'',ref:''}:raceDraft().sanctions[index];modal('Sanción · '+pilots[pilot].name,`<p>${circuits[adminCircuit].name} · Split ${adminSplit} · ${pilots[pilot].team}</p><form onsubmit="event.preventDefault();saveSanction(${pilot},${index})"><div class="form-grid"><label class="field">Tipo<select id="penalty-kind">${['Decisión FIA','Sanción reglamentaria'].map(k=>`<option ${x.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label class="field">Segundos de sanción<input id="penalty-seconds" type="number" min="0.001" step="0.001" required value="${esc(x.seconds)}" placeholder="Introduce los segundos"></label><label class="field full">Artículo o regla aplicada<input id="penalty-rule" required value="${esc(x.rule)}" placeholder="Referencia del reglamento"></label><label class="field full">Justificación<textarea id="penalty-reason" required placeholder="Explica la infracción y la decisión">${esc(x.reason)}</textarea></label><label class="field full">Referencia oficial<input id="penalty-ref" required value="${esc(x.ref)}" placeholder="Acta, resolución o anuncio oficial"></label></div><div class="info" style="margin-top:18px">La sanción se añade al borrador. Los segundos no cambian automáticamente las posiciones ni generan una multa.</div><div class="actions"><button class="btn primary" type="submit">Añadir al borrador</button><button class="btn" type="button" onclick="closeModal()">Cancelar</button></div></form>`)}
function saveSanction(pilot,index){let seconds=Number($('#penalty-seconds').value),reason=$('#penalty-reason').value.trim(),rule=$('#penalty-rule').value.trim(),ref=$('#penalty-ref').value.trim();if(!Number.isFinite(seconds)||seconds<=0||!reason||!rule||!ref){toast('Completa los segundos, la regla, la justificación y la referencia.');return}let record={pilot,kind:$('#penalty-kind').value,seconds,reason,rule,ref};if(index===null)raceDraft().sanctions.push(record);else raceDraft().sanctions[index]=record;closeModal();render();toast('Decisión añadida al borrador. No aplicada.')}
function removeSanction(i){captureRace();raceDraft().sanctions.splice(i,1);render();toast('Decisión retirada del borrador.')}
function youtubeId(value){try{let u=new URL(value);if(u.protocol!=='https:')return null;let h=u.hostname.toLowerCase(),id=h==='youtu.be'?u.pathname.split('/')[1]:['youtube.com','www.youtube.com','m.youtube.com'].includes(h)?(u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts)\/([^/]+)/)?.[1]):null;return /^[a-zA-Z0-9_-]{11}$/.test(id||'')?id:null}catch{return null}}
function embedVideo(value,selector){const id=youtubeId(value);if(!id){toast('Introduce una URL de vídeo de YouTube válida.');return}$(selector).innerHTML=`<iframe title="Vídeo de vuelta rápida" src="https://www.youtube-nocookie.com/embed/${id}" allow="fullscreen; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`}
function previewScheduleVideo(){embedVideo($('#schedule-url').value.trim(),'#schedule-preview')}
let schedulePending=null;
function reviewSchedule(){const value={round:$('#schedule-round').value,date:$('#schedule-date').value,time:$('#schedule-time').value,url:$('#schedule-url').value.trim(),lap:$('#schedule-lap').value.trim()};if(!Number.isInteger(+value.round)||+value.round<1||!value.date||!value.time||(value.url&&!youtubeId(value.url))||(value.lap&&!/^\d+:[0-5]\d\.\d{3}$/.test(value.lap))){toast('Revisa la fecha, hora, número de carrera, URL o tiempo de referencia.');return}schedulePending={key:adminCircuit,value};modal('Revisar programación',`<p>${circuits[adminCircuit].name}</p><div class="summary-row"><span>Carrera</span><strong>${esc(value.round)}</strong></div><div class="summary-row"><span>Fecha y hora · Madrid</span><strong>${esc(value.date)} · ${esc(value.time)}</strong></div><div class="summary-row"><span>Vídeo</span><span>${value.url?'Preparado':'Pendiente'}</span></div><div class="summary-row"><span>Tiempo de referencia</span><strong>${esc(value.lap||'Sin registrar')}</strong></div><p>Se guardará solo en este navegador para probar el flujo.</p>${btn('Guardar programación de prueba','saveSchedule()',true)}`)}
function saveSchedule(){if(!schedulePending)return;let next={...savedSchedules,[schedulePending.key]:schedulePending.value};try{localStorage.setItem('bugambra-schedules-v1',JSON.stringify(next));savedSchedules=next;schedulePending=null;closeModal();render();toast('Programación guardada en este navegador.')}catch{toast('No se pudo guardar. La programación anterior se conserva.')}}
reviewRace=function(){captureRace();const d=raceDraft();if(!d.reason.trim()){toast('Añade el motivo y la referencia oficial.');$('#reason').focus();return}const finals=[],qualys=[];for(const r of d.rows){if(r.q&&(!Number.isInteger(+r.q)||+r.q<1||+r.q>pilots.length||qualys.includes(r.q))){toast('Revisa las posiciones de qualy: deben ser válidas y únicas.');return}if(r.q)qualys.push(r.q);if(r.status==='Clasificado'){if(!r.pos||!Number.isInteger(+r.pos)||+r.pos<1||+r.pos>pilots.length||finals.includes(r.pos)){toast('Revisa las posiciones finales: deben ser válidas y únicas.');return}finals.push(r.pos)}}let fastest=d.rows.findIndex(r=>r.fast);modal('Revisar acta e impacto',`<p>${circuits[adminCircuit].name} · Split ${adminSplit}</p>${d.rows.map((r,i)=>`<div class="summary-row"><strong>${pilots[i].name}</strong><span>Qualy: ${circuits[adminCircuit].status==='cerrada'?(pilots[i].q??'—'):'—'} → ${esc(r.q||'—')}<br>Final: ${circuits[adminCircuit].status==='cerrada'?(pilots[i].pos??'—'):'—'} → ${esc(r.pos||'—')}<br>${circuits[adminCircuit].status==='cerrada'?(pilots[i].status||'Clasificado'):'Sin registro'} → ${esc(r.status)}</span></div>`).join('')}<div class="summary-row"><span>Vuelta rápida</span><strong>${fastest<0?'Sin marcar':pilots[fastest].name}</strong></div><h3 style="margin-top:20px">Decisiones propuestas</h3>${d.sanctions.map(s=>`<p><strong>${pilots[s.pilot].name} · +${s.seconds} s</strong><br>${esc(s.kind)} · ${esc(s.rule)}<br>${esc(s.reason)}<br>Ref. ${esc(s.ref)}</p>`).join('')||'<p>Sin sanciones en el borrador.</p>'}<p>Motivo: ${esc(d.reason)}</p><div class="info error">Impacto pendiente de los servicios de la liga. No se puede confirmar todavía.</div><div class="summary-row"><span>Liquidaciones que deben revertirse</span><span>Pendiente de identificar</span></div><div class="summary-row"><span>Posiciones, puntos, ratings y premios · antes → después</span><span>Cálculo no disponible</span></div><label class="checkbox"><input type="checkbox" disabled>Confirmar tras revisar el impacto y las liquidaciones.</label><button class="btn primary" disabled>Confirmar acta</button><p class="small">El borrador se conserva durante esta sesión. No se ha escrito en la liga.</p>`)};
const breakdownFields=[['initial','Presupuesto inicial'],['market','Mercado · ledger'],['clauses','Ajustes / cláusulas'],['pointsIncome','Puntos'],['pole','Pole'],['fast','Vuelta rápida'],['participation','Participación'],['clean','Sin sanciones'],['rivalry','Rivalidad'],['season','Premio de temporada'],['adjustment','Ajustes manuales']];
adminEconomy=function(){return `<p class="small workspace-note">Resumen de escuderías y mercado por split. Importes ficticios registrados, sin aplicar reglas nuevas.</p><details class="card pad eco-rules"><summary>▸ Reglas económicas del split</summary><div class="info">Las reglas y sus importes se obtendrán de la configuración de la liga. Esta vista no define ni modifica las fórmulas.</div><div class="rules-grid">${['Puntos, pole y vuelta rápida','Participación y sin sanciones','Rivalidad y premio de temporada'].map(x=>`<div><strong>${x}</strong><small>Configuración pendiente de conectar</small></div>`).join('')}</div></details><div class="admin-toolbar">${splitSelect('economy-split',economySplit,"economySplit=this.value;render()")}<div class="compact-actions">${btn('Registrar acuerdo de WhatsApp',"agreementForm(0,null,'adjustment')",true)}${btn('Boletín económico','economicBulletin()')}</div></div>${economySplit!=='1'?'<div class="card empty">No hay registros de ejemplo en este split. Selecciona Split 1 para explorar economía y contratos.</div>':`<div class="section-title"><h2>Resumen de escuderías</h2><span class="small">Saldos y desglose · demo</span></div><div class="eco-teams">${demoTeams.map((t,i)=>`<section class="card eco-team" style="--team-color:${teamColor(t.name)}"><div class="card-top"><h3>${t.name}</h3>${tag(t.points+' PTS')}</div><div class="small">Presupuesto disponible</div><div class="balance">${money(t.balance)}</div><div class="compact-actions">${btn('Ajustar saldo',`agreementForm(${i},null,'adjustment')`)}${btn('Movimientos',`teamLedger(${i})`)}${btn('Por carrera',`openRaceEconomy(${i})`)}</div><details><summary>Ver desglose económico ↓</summary><div class="breakdown">${breakdownFields.map(([k,l])=>`<div><span>${l}</span><strong class="${k!=='initial'&&t[k]>0?'green-text':''}">${k!=='initial'&&t[k]>0?'+':''}${money(t[k])}</strong></div>`).join('')}<div><strong>Total disponible</strong><strong>${money(t.balance)}</strong></div></div></details></section>`).join('')}</div>${raceEconomySection(true)}<section class="card pad"><div class="card-top"><div><div class="eyebrow">PILOTOS Y MERCADO</div><h2 style="margin-top:8px">Precios y contratos</h2></div></div><div class="eco-subnav"><div class="tabs" style="margin:0">${['precios','rendimiento'].map(x=>`<button class="${economyMode===x?'active':''}" onclick="economyMode='${x}';render()">${x==='precios'?'Precios':'Rendimiento'}</button>`).join('')}</div><input id="market-search" type="search" placeholder="Buscar piloto o equipo" value="${esc(economySearch)}" aria-label="Buscar piloto o equipo" oninput="economySearch=this.value;document.querySelector('#market-content').innerHTML=marketRows()"></div><div id="market-content">${marketRows()}</div></section>`}`};
function marketRows(){return demoTeams.map((t,ti)=>{let contracts=demoContracts.filter(c=>pilots[c.pilot].team===t.name&&(pilots[c.pilot].name+' '+t.name).toLowerCase().includes(economySearch.toLowerCase()));if(!contracts.length)return '';return `<div class="market-group" style="--team-color:${teamColor(t.name)}"><h3>${t.name}</h3>${contracts.map(c=>{const p=pilots[c.pilot];return `<div class="market-row"><div class="market-name"><strong>${p.name}</strong><small>${economyMode==='precios'?'Precio de compra registrado':'Puntos publicados · temporada demo'}</small></div>${economyMode==='precios'?`<div><button class="price-button" onclick="agreementForm(${ti},${c.pilot},'price')">${money(c.price)} ✎</button><small>Editar precio</small></div><div><small>Próximo split</small><strong>Sin acuerdo</strong></div><div class="compact-actions">${btn('Registrar acuerdo',`agreementForm(${ti},${c.pilot},'renewal')`)}${btn('Ficha económica',`contractDetail(${c.pilot})`)}</div>`:`<div><strong>${p.points??'Pendiente'}</strong><small>Puntos de temporada</small></div><div><strong>${p.q??'—'} / ${p.pos??'—'}</strong><small>Monza · qualy / carrera</small></div><div><strong>${p.status||'Clasificado'}</strong><small>Estado registrado</small></div>`}</div>`}).join('')}</div>`}).join('')||'<div class="empty">No hay pilotos que coincidan con la búsqueda.</div>'}
function contractDetail(i){const c=demoContracts[i],p=pilots[i];modal('Ficha económica · '+p.name,`<p>${p.team} · Split 1 · datos ficticios</p><div class="summary-row"><span>Precio de compra cobrado</span><strong>${money(c.price)}</strong></div><div class="summary-row"><span>Mantenimiento registrado · Monza</span><strong>${money(c.retention)}</strong></div><div class="summary-row"><span>Cláusula registrada · Monza</span><strong>${money(c.clause)}</strong></div><div class="summary-row"><span>Próximo split</span><span>Sin acuerdo registrado</span></div><p>Los valores son ejemplos de registros. Una renovación o cláusula se registra después del anuncio oficial por WhatsApp.</p><div class="actions">${btn('Registrar renovación / cláusula',`agreementForm(${demoTeams.findIndex(t=>t.name===p.team)},${i},'renewal')`,true)}</div>`)}
function teamLedger(i){const t=demoTeams[i];modal('Movimientos · '+t.name,`<p>Split 1 · consulta de registros ficticios</p>${i===0?ledgerRows():`<div class="info">Desglose disponible en el resumen. No hay asientos detallados de ejemplo para esta escudería.</div>`}<div class="summary-row"><span>Saldo registrado</span><strong>${money(t.balance)}</strong></div>`)}
function economicBulletin(){modal('Boletín económico',`<p>Split ${economySplit} · vista de ejemplo</p>${economySplit==='1'?demoTeams.map(t=>`<div class="summary-row"><strong>${t.name}</strong><span>${money(t.balance)} · ${t.points} pts</span></div>`).join(''):'<div class="empty">Sin registros.</div>'}<div class="info" style="margin-top:16px">El boletín oficial requiere los registros y el servicio de exportación de la liga.</div><div class="actions"><button class="btn" disabled>Descargar PDF oficial</button></div>`)}
function agreementForm(teamIndex,pilotIndex,type){if(economySplit!=='1'){toast('Selecciona el split de demostración.');return}activeEconomyTeam=teamIndex;activeEconomyPilot=pilotIndex;const t=demoTeams[teamIndex];modal('Registrar acuerdo · '+t.name,`<p>Introduce un acuerdo ya anunciado por WhatsApp. Split 1 · saldo de ejemplo ${money(t.balance)}.</p><form id="economy-form" onsubmit="event.preventDefault();reviewEconomy()"><div class="form-grid"><label class="field">Fecha del acuerdo<input id="agreement-date" type="date" required></label><label class="field">Referencia oficial<input id="agreement-ref" required placeholder="Referencia de WhatsApp"></label><label class="field full">Operación<select id="operation" onchange="economyFields()">${[['adjustment','Ajuste de presupuesto'],['price','Cambio de precio de compra'],['signing','Fichaje'],['renewal','Renovación / cláusula'],['fine','Sanción económica aprobada']].map(([k,l])=>`<option value="${k}" ${type===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="field full">Piloto<select id="agreement-driver" onchange="activeEconomyPilot=this.value?pilots.findIndex(p=>p.name===this.value):null;economyFields()"><option value="">No aplica</option>${pilots.filter(p=>p.team===t.name).map(p=>`<option value="${esc(p.name)}" ${pilotIndex!==null&&p.name===pilots[pilotIndex].name?'selected':''}>${p.name}</option>`).join('')}</select></label><div class="field full" id="amount-fields"></div><label class="field full">Motivo y concepto<textarea id="agreement-reason" required placeholder="Explica el acuerdo oficial"></textarea></label><label class="field full">Autor<input id="agreement-author" required placeholder="Administrador responsable"></label></div><div class="actions"><button class="btn primary" type="submit">Revisar asiento</button></div></form>`);economyFields()}
economyFields=function(){const price=$('#operation').value==='price',p=activeEconomyPilot===null?null:demoContracts[activeEconomyPilot];$('#amount-fields').innerHTML=price?`<div class="form-grid"><label class="field">Precio ya cobrado (M€)<input id="old-price" type="number" min="0" step="0.01" required value="${p?p.price:''}" ${p?'readonly':''}></label><label class="field">Nuevo precio oficial (M€)<input id="new-price" type="number" min="0" step="0.01" required placeholder="Importe del acuerdo"></label></div>`:`<label class="field">Importe oficial con signo (M€)<input id="official-amount" type="number" step="0.01" required placeholder="Positivo: ingreso · negativo: cargo"></label>`};
reviewEconomy=function(){const t=demoTeams[activeEconomyTeam],price=$('#operation').value==='price',before=price?Number($('#old-price').value):null,after=price?Number($('#new-price').value):null,delta=price?before-after:Number($('#official-amount').value),balance=Math.round((t.balance+delta)*100)/100,missing=balance<0;let driver=$('#agreement-driver').value,ref=$('#agreement-ref').value.trim(),author=$('#agreement-author').value.trim(),reason=$('#agreement-reason').value.trim(),date=$('#agreement-date').value;if(!ref||!author||!reason||!date||!Number.isFinite(delta)||(price&&(!driver||before<0||after<0))){toast('Completa los datos oficiales y el piloto para cambiar un precio.');return}modal('Revisar acuerdo · '+t.name,`<p>Split 1 · ${esc(driver||'Sin piloto asociado')}</p>${price?`<div class="summary-row"><span>Precio cobrado → precio oficial</span><strong>${money(before)} → ${money(after)}</strong></div>`:''}<div class="summary-row"><span>${price?(delta>=0?'Devolver diferencia':'Cobrar diferencia'):'Importe oficial'}</span><strong>${delta>0?'+':''}${money(delta)}</strong></div><div class="summary-row"><span>Saldo antes → después</span><strong>${money(t.balance)} → ${money(balance)}</strong></div><div class="ledger-preview"><h3>Asiento y auditoría propuestos</h3><div class="summary-row"><span>Fecha / referencia</span><span>${esc(date)} · ${esc(ref)}</span></div><div class="summary-row"><span>Autor</span><span>${esc(author)}</span></div><p>${esc(reason)}</p></div><div class="info ${missing?'error':''}" style="margin-top:16px">${missing?'Saldo insuficiente. Faltan '+money(-balance)+'. Operación bloqueada.':'Vista previa. El presupuesto inicial no se modifica y todavía no se ha registrado el asiento.'}</div><label class="checkbox"><input id="confirm-ledger" type="checkbox" ${missing?'disabled':''} onchange="document.querySelector('#simulate-ledger').disabled=!this.checked">He revisado el acuerdo y el importe.</label><button id="simulate-ledger" class="btn primary" disabled onclick="simulateWrite()">Simular guardado</button><p class="small">La escritura real no está conectada. Esta prueba mostrará el error sin modificar saldos.</p>`)};
telemetry=function(){const s=scheduleData(teleCircuit),c=circuits[teleCircuit];return title('DATOS DEL CIRCUITO','Telemetría','La vuelta de referencia, preparada antes de la carrera.')+`<div class="card-top"><h2>${c.track}</h2><select class="btn" aria-label="Circuito" onchange="teleCircuit=this.value;render()">${Object.keys(circuits).map(k=>`<option value="${k}" ${k===teleCircuit?'selected':''}>${circuits[k].name}</option>`).join('')}</select></div><div class="grid"><section class="card pad"><div class="hotlap-preview" id="telemetry-preview"><div><span class="play-round">▶</span><h3>${c.name}</h3><p>${s.url?'Vídeo de prueba disponible':'Vídeo pendiente de publicación'}</p>${s.url?btn('Reproducir vuelta rápida',"playSavedHotlap()",true):''}</div></div><p class="small">${savedSchedules[teleCircuit]?'Programación de prueba guardada en este navegador.':'No hay un vídeo oficial conectado a esta demostración.'}</p></section><section class="card pad"><div class="eyebrow">PROGRAMACIÓN</div><h2 style="margin-top:12px">${c.name}</h2><div class="summary-row"><span>Fecha</span><strong>${esc(s.date)}</strong></div><div class="summary-row"><span>Hora · Madrid</span><strong>${esc(s.time)}</strong></div><div class="summary-row"><span>Vuelta de referencia</span><strong>${esc(s.lap||'Pendiente')}</strong></div><div class="summary-row"><span>Acta</span><strong>${c.status==='cerrada'?'Publicada · ejemplo':'Pendiente'}</strong></div><p class="small">Sin datos de sectores ni velocidades registrados.</p>${c.status==='cerrada'?btn('Ver acta',`race('${teleCircuit}')`):''}</section></div>`};
function playSavedHotlap(){embedVideo(scheduleData(teleCircuit).url,'#telemetry-preview')}
updateNav=function(){legacyUpdateNav();if(current==='admin'){$('#app').dataset.page='admin';if(adminTab==='carreras'&&adminSplit==='1')raceDraft().rows.forEach((r,i)=>{const input=document.querySelector('#pos-'+i);if(input)input.disabled=r.status!=='Clasificado'})}};
const originalRender=render;render=function(){originalRender();if(current==='admin'&&adminTab==='carreras'&&adminSplit==='1')raceDraft().rows.forEach((r,i)=>{const input=document.querySelector('#pos-'+i);if(input)input.disabled=r.status!=='Clasificado'})};
const originalAdmin=admin;admin=function(){return `<div class="admin-view-switch">${tag('ADMIN · DEMO','amber')}${btn('← Volver al panel de piloto',"go('inicio')")}</div>`+originalAdmin()};
let raceEconomyTeam=0,raceEconomyCircuit='monza';
// Link existing demo ledger entries explicitly to their GP; do not allocate season totals.
const gpLedgerIndices={monza:[0],spa:[2]};
const gpCategories=[['points','Puntos'],['pole','Pole'],['fastest','Vuelta rápida'],['participation','Participación'],['clean','Sin sanciones'],['rivalry','Rivalidad'],['prize','Premios'],['fine','Sanciones económicas aprobadas'],['adjustment','Ajustes manuales asociados al GP']];
function gpEntries(teamId,key){return teamId===0?(gpLedgerIndices[key]||[]).map(index=>({index,entry:moves[index]})):[]}
function raceEconomySection(isAdmin){const ti=isAdmin?raceEconomyTeam:0;return `<section class="card pad gp-economy gp-jump" id="race-economy"><div class="card-top"><div><div class="eyebrow">ECONOMÍA · GRAN PREMIO</div><h2 style="margin-top:8px">Economía por carrera</h2></div>${tag('DEMO')}</div><div class="gp-controls">${isAdmin?`<label class="field">Escudería<select id="gp-economy-team" onchange="raceEconomyTeam=Number(this.value);refreshRaceEconomy(true)">${demoTeams.map((t,i)=>`<option value="${i}" ${i===ti?'selected':''}>${t.name}</option>`).join('')}</select></label>`:`<div class="field">Escudería<strong>${demoTeams[0].name}</strong></div>`}<label class="field">Gran Premio<select id="gp-economy-circuit" onchange="raceEconomyCircuit=this.value;refreshRaceEconomy(${isAdmin})">${Object.entries(circuits).map(([k,c])=>`<option value="${k}" ${k===raceEconomyCircuit?'selected':''}>${c.name} · ${c.date.slice(0,6)}</option>`).join('')}</select></label></div><div id="gp-economy-detail">${raceEconomyDetail(ti,raceEconomyCircuit)}</div></section>`}
function refreshRaceEconomy(isAdmin){$('#gp-economy-detail').innerHTML=raceEconomyDetail(isAdmin?raceEconomyTeam:0,raceEconomyCircuit)}
function raceEconomyDetail(teamId,key){const c=circuits[key],records=gpEntries(teamId,key),hasRecords=records.length>0,net=records.reduce((sum,x)=>sum+x.entry.amount,0),last=records.length?records[records.length-1].entry:null;return `<div class="card-top"><h3>${c.track}</h3>${tag(c.status!=='cerrada'?'PRÓXIMA':hasRecords?'PARCIAL':'PENDIENTE',c.status!=='cerrada'?'':'amber')}</div><div class="gp-summary gp-summary-clean"><div><span>Neto registrado</span><strong>${hasRecords?(net>0?'+':'')+money(net):'—'}</strong></div><div><span>Saldo posterior</span><strong>${last?money(last.balance):'—'}</strong></div></div><div class="gp-ledger">${hasRecords?records.map(x=>`<button class="ledger-row" onclick="movement(${x.index})"><span class="row-info"><h3>${x.entry.concept}</h3><p>${x.entry.date}</p></span><span class="amount ${x.entry.amount>0?'green-text':''}">${x.entry.amount>0?'+':''}${money(x.entry.amount)} <span aria-hidden="true">↗</span></span></button>`).join(''):`<div class="empty">${c.status!=='cerrada'?'Disponible después de la carrera.':'Sin movimientos registrados.'}</div>`}</div><details class="gp-more"><summary>Ver detalle por concepto</summary><div class="gp-detail"><div><h3>Ingresos</h3>${gpCategories.slice(0,7).map(([id,label])=>gpCategoryLine(id,label,records)).join('')}${records.some(x=>x.entry.category==='Ingresos deportivos')?`<div class="gp-category"><span>Sin desglosar</span><strong class="green-text">+${money(records.filter(x=>x.entry.category==='Ingresos deportivos').reduce((n,x)=>n+x.entry.amount,0))}</strong></div>`:''}</div><div><h3>Cargos y ajustes</h3>${gpCategories.slice(7).map(([id,label])=>gpCategoryLine(id,label,records)).join('')}<div class="summary-row"><span>Liquidación</span><span>Pendiente</span></div></div></div><p class="gp-period-note">Los importes pendientes no equivalen a cero. Solo se muestran movimientos vinculados a este GP; el neto puede ser parcial.</p></details><div class="gp-bottom"><span class="small">${hasRecords?'Conciliación pendiente':'Sin liquidación'}</span><button class="text-link" onclick="race('${key}')">${c.status==='cerrada'?'Ver acta':'Ver carrera'} ↗</button></div>`}
function gpCategoryLine(id,label,records){const category={prize:'Premios',fine:'Sanciones económicas aprobadas',adjustment:'Ajustes manuales'}[id],matches=category?records.filter(x=>x.entry.category===category):[];return `<div class="gp-category"><span>${label}</span>${matches.length?`<strong class="green-text">${money(matches.reduce((n,x)=>n+x.entry.amount,0))}</strong>`:'<span class="pending">Pendiente</span>'}</div>`}
function openRaceEconomy(teamId){raceEconomyTeam=teamId;render();document.querySelector('#race-economy')?.scrollIntoView({block:'start'})}
const teamWithoutGp=team;team=function(){return teamWithoutGp()+raceEconomySection(false)};
route();
